#include <iostream>
#include <string>
#include <fstream>
#include <omniORB4/CORBA.h>

#include "echo.hh" // Generated by the IDL compiler

using namespace std;

int main(int argc, char* argv[])
{
  if (argc < 2)
    {
      cerr << "Usage: " << argv[0] << " <message>" << endl;
      return 1;
    }

  const string message(argv[1]);
  
  try
    {
      // Initialize the ORB.
      CORBA::ORB_var orb = CORBA::ORB_init(argc, argv);

      // Read the IOR from the file.
      ifstream ior_file("echo.ior");
      string ior_string;
      if (ior_file.is_open())
	{
	  getline(ior_file, ior_string);
	  ior_file.close();
	}
      else
	{
	  cerr << "Unable to open echo.ior file" << endl;
	  return 1;
	}

      // Obtain the object reference from the IOR string.
      CORBA::Object_var obj = orb->string_to_object(ior_string.c_str());
      Echo_var echo_ref = Echo::_narrow(obj);

      if (CORBA::is_nil(echo_ref))
	{
	  cerr << "Invalid object reference." << endl;
	  return 1;
	}

      // Invoke the echoString operation.
      CORBA::String_var result = echo_ref->echoString(message.c_str());
      cout << "Received from server: " << result.in() << endl;

      // Cleanup.
      orb->destroy();

    }
  catch (CORBA::Exception& ex)
    {
      cerr << "CORBA exception: " << ex._name() << endl;
      return 1;
    }

  return 0;
}
